/** Appearance registry result, generated by src/appearance/integration.mjs */
declare module 'virtual:vergil/appearance' {
    /** Display name per language, e.g. { "zh-CN": "<Chinese name>", "en": "Island" } */
    export type AppearanceLabels = Record<string, string>;

    export interface SkinEntry {
        name: string;
        labels: AppearanceLabels;
        /** Default scheme: applied when a visitor switches to this skin */
        recommendedScheme: string;
        /** Scheme IDs selectable under this skin: A–I and K for the classic skin, their own bundled ones for other skins */
        schemes: string[];
    }

    export interface SchemeEntry {
        id: string;
        /** Short label shown under the color dot on the panel */
        short: string;
        labels: AppearanceLabels;
        /** Color of the dot on the panel */
        swatch: string;
        /** Color of the palette icon once selected */
        icon: string;
    }

    export const contract: number;
    export const skins: SkinEntry[];
    export const schemes: SchemeEntry[];
}

/** Imports the CSS of the enabled skins and schemes in order */
declare module 'virtual:vergil/appearance-styles' {}
